import {Config} from 'alinea'
import {createCMS} from 'alinea/next'

const editor = Config.role('Editor', {
  description: 'Edits and publishes content, cannot change settings',
  permissions(policy) {
    policy.set(
      {
        allow: {
          read: true,
          create: true,
          update: true,
          publish: true,
          archive: true,
          reorder: true,
          move: true,
          upload: true
        }
      },
      {
        root: cms.workspaces.main.settings,
        deny: {create: true, update: true, publish: true, archive: true}
      }
    )
  }
})

export const cms = createCMS({
  roles: {editor},
  // schema, workspaces ...
})

policy.set(
  // No target: applies to everything
  {allow: {read: true}},
  // A workspace or root, as defined in your config
  {root: cms.workspaces.main.pages, allow: {update: true}},
  // Every entry of a type, or one field of a type
  {type: BlogPost, allow: {create: true}},
  {field: BlogPost.price, deny: {update: true}},
  // One entry (and everything below it)
  {id: entryId, allow: {all: true}},
  // Every entry in a locale, null for untranslated entries
  {locale: 'fr', allow: {update: true}}
)

const viewer = Config.role('Viewer', {
  permissions(policy) {
    policy.set({allow: {read: true}})
  }
})

const translator = Config.role('Translator', {
  description: 'Translates pages into French',
  permissions(policy) {
    policy.set(
      {allow: {read: true}},
      {locale: 'fr', allow: {update: true, publish: true}}
    )
  }
})

const editor = Config.role('Editor', {
  permissions(policy) {
    policy.set(
      {allow: {read: true, update: true, publish: true}},
      {field: BlogPost.price, deny: {update: true}}
    )
  }
})

const landingPageEditor = Config.role('Landing page editor', {
  permissions(policy) {
    policy.set(
      {
        workspace: cms.workspaces.main,
        allow: {read: true},
        grant: 'explicit'
      },
      {
        root: cms.workspaces.main.pages,
        allow: {read: true},
        grant: 'explicit'
      },
      {
        id: landingPageId,
        allow: {all: true}
      }
    )
  }
})

import {Config, Query} from 'alinea'

const guestAuthor = Config.role('Guest author', {
  async permissions(policy, graph) {
    const posts = await graph.find({
      type: BlogPost,
      filter: {author: {has: {_entry: guestAuthorId}}},
      select: Query.id
    })
    policy.set(
      {workspace: cms.workspaces.main, allow: {read: true}, grant: 'explicit'},
      {root: cms.workspaces.main.pages, allow: {read: true}, grant: 'explicit'}
    )
    for (const id of posts) policy.set({id, allow: {read: true, update: true}})
  }
})

import {expect, test} from 'bun:test'
import {cms} from '@/cms'

test('editors cannot change settings', async () => {
  const policy = await cms.createPolicy(['editor'])
  expect(policy.canUpdate({workspace: 'main', root: 'pages'})).toBe(true)
  expect(policy.canUpdate({workspace: 'main', root: 'settings'})).toBe(false)
})
